async def act(page):
    """
    High-level plan:
    1. Navigate to the Magento Manage Products grid using a relative goto.
    2. Filter the grid for "Nona Fitness Tank" and open its edit page.
    3. Open the "Associated Products" tab.
    4. For Blue and Purple, attempt to create or add an associated simple product with Size = XXS by using accessible controls (buttons, comboboxes, textboxes, save buttons) via get_by_role only.
    5. Save the configurable product.

    Notes about knowledge-base helper functions: there are no provided helper functions in the knowledge base for interacting with this site, so this implementation uses Playwright's accessibility-based APIs only (get_by_role, select_option). Each attempt uses get_by_role selectors exclusively, as required.
    """

    # 1) Navigate to Manage Products
    await page.goto("/index.php/admin/catalog_product/index/")
    # small wait for the grid to load
    await page.wait_for_timeout(1000)

    # 2) Try to filter product grid by product name using accessible textbox and Search button
    # Use a few different get_by_role attempts depending on how the grid is labeled
    try:
        # common case: a textbox labeled 'Name'
        await page.get_by_role("textbox", name="Name").fill("Nona Fitness Tank")
        await page.get_by_role("button", name="Search").click()
    except Exception:
        try:
            # fallback: first textbox on the page may be the name filter
            await page.get_by_role("textbox").nth(0).fill("Nona Fitness Tank")
            await page.get_by_role("button", name="Search").click()
        except Exception:
            # last resort: try pressing Enter in the first textbox
            try:
                await page.get_by_role("textbox").nth(0).press("Enter")
            except Exception:
                # If filtering fails, continue and try to find the product link directly
                pass

    # wait for results to appear
    await page.wait_for_timeout(1000)

    # 3) Open the product edit page for 'Nona Fitness Tank'
    # Prefer an accessible link with that exact product name
    try:
        await page.get_by_role("link", name="Nona Fitness Tank").click()
    except Exception:
        # If a link with exact name isn't present, try a link that contains the text (case-insensitive substring match via name works normally)
        try:
            await page.get_by_role("link", name="Nona Fitness").click()
        except Exception:
            # If that still fails, give up here since the product edit can't be reached reliably
            return

    # wait for the product edit form to load
    await page.wait_for_timeout(1000)

    # 4) Open the 'Associated Products' tab
    try:
        await page.get_by_role("tab", name="Associated Products").click()
    except Exception:
        try:
            # Sometimes implemented as a link or button
            await page.get_by_role("link", name="Associated Products").click()
        except Exception:
            try:
                await page.get_by_role("button", name="Associated Products").click()
            except Exception:
                # If the tab can't be clicked, proceed — the associated products area might already be visible
                pass

    await page.wait_for_timeout(800)

    # Helper: attempt to create/add an associated simple product for a given color and set Size=XXS
    async def create_associated_for_color(color_name: str):
        # Try likely buttons to start creation of a simple associated product
        create_button_names = [
            "Create Simple Product",
            "Add Associated Products",
            "Add",
            "Create",
            "Add New",
        ]

        clicked_create = False
        for btn in create_button_names:
            try:
                await page.get_by_role("button", name=btn).click()
                clicked_create = True
                break
            except Exception:
                continue

        # If none of the obvious create buttons exist, try an alternate approach: a link in the associated products area
        if not clicked_create:
            try:
                await page.get_by_role("link", name="Create Simple Product").click()
                clicked_create = True
            except Exception:
                pass

        # If no create flow is available, return False indicating we could not create
        if not clicked_create:
            return False

        # Give the inline form a moment to appear
        await page.wait_for_timeout(600)

        # Set Color attribute: prefer a combobox named 'Color', fallback to a textbox
        try:
            await page.get_by_role("combobox", name="Color").select_option(option_name=color_name)
        except Exception:
            try:
                await page.get_by_role("textbox", name="Color").fill(color_name)
            except Exception:
                # best-effort: try to click a button/option labeled with the color
                try:
                    await page.get_by_role("button", name=color_name).click()
                except Exception:
                    pass

        # Set Size to XXS: prefer a combobox named 'Size', fallback to textbox
        try:
            await page.get_by_role("combobox", name="Size").select_option(option_name="XXS")
        except Exception:
            try:
                await page.get_by_role("textbox", name="Size").fill("XXS")
            except Exception:
                # If the option is not present, attempt to add via a button 'Add New Size' then fill
                try:
                    await page.get_by_role("button", name="Add New Size").click()
                    await page.wait_for_timeout(300)
                    await page.get_by_role("textbox", name="Option Label").fill("XXS")
                    await page.get_by_role("button", name="OK").click()
                except Exception:
                    pass

        # Save the newly created associated simple product. Try Save first, then Save and Continue Edit.
        try:
            await page.get_by_role("button", name="Save").click()
        except Exception:
            try:
                await page.get_by_role("button", name="Save and Continue Edit").click()
            except Exception:
                # not able to locate a save button for the inline flow
                return False

        # Allow UI to update and return success
        await page.wait_for_timeout(1000)
        return True

    # 5) Create associated products for Blue and Purple
    await create_associated_for_color("Blue")
    await create_associated_for_color("Purple")

    # 6) Save the configurable product itself (final save on the product edit page)
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        try:
            await page.get_by_role("button", name="Save and Continue Edit").click()
        except Exception:
            # If neither save is found, just finish — we attempted best-effort saves above
            pass

    # Wait a moment for the save to complete
    await page.wait_for_timeout(1200)

    return

