async def act(page):
    """
    High-level plan:
    1. Navigate to the Magento Manage Products grid using a relative goto.
    2. Filter the grid for "Nona Fitness Tank" and open its edit page.
    3. Open the "Associated Products" tab.
    4. For Blue and Purple, attempt to create or add an associated simple product with Size = XXS by using accessible controls (buttons, comboboxes, textboxes, save buttons) via get_by_role only.
    5. Save the configurable product.

    Notes about knowledge-base helper functions: there are no provided helper functions in the knowledge base for interacting with this site, so this implementation uses Playwright's accessibility-based APIs only (get_by_role, select_option). Each attempt uses get_by_role selectors exclusively, as required.
    """

    # 1) Navigate to Manage Products
    await page.goto("/index.php/admin/catalog_product/index/")
    # small wait for the grid to load
    await page.wait_for_timeout(1000)

    # 2) Try to filter product grid by product name using accessible textbox and Search button
    # Use a few different get_by_role attempts depending on how the grid is labeled
    try:
        # common case: a textbox labeled 'Name'
        await page.get_by_role("textbox", name="Name").fill("Nona Fitness Tank")
        await page.get_by_role("button", name="Search").click()
    except Exception:
        try:
            # fallback: first textbox on the page may be the name filter
            await page.get_by_role("textbox").nth(0).fill("Nona Fitness Tank")
            await page.get_by_role("button", name="Search").click()
        except Exception:
            # last resort: try pressing Enter in the first textbox
            try:
                await page.get_by_role("textbox").nth(0).press("Enter")
            except Exception:
                # If filtering fails, continue and try to find the product link directly
                pass

    # wait for results to appear
    await page.wait_for_timeout(1000)

    # 3) Open the product edit page for 'Nona Fitness Tank'
    # Prefer an accessible link with that exact product name
    try:
        await page.get_by_role("link", name="Nona Fitness Tank").click()
    except Exception:
        # If a link with exact name isn't present, try a link that contains the text (case-insensitive substring match via name works normally)
        try:
            await page.get_by_role("link", name="Nona Fitness").click()
        except Exception:
